package com.pixilife.android;import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.os.*;import android.provider.CalendarContract;import java.util.*;import java.util.regex.*;
public class CalendarVoiceReceiver extends BroadcastReceiver {private static long token;@Override public void onReceive(Context c,Intent i){if(!"heard".equals(i.getStringExtra("type")))return;String q=i.getStringExtra("value");if(q==null)return;long mine=++token;new Handler(Looper.getMainLooper()).postDelayed(()->{if(mine==token)run(c.getApplicationContext(),q);},2000);}private void run(Context c,String q){String t=q.toLowerCase(Locale.ROOT);if(c.checkSelfPermission(Manifest.permission.READ_CALENDAR)!=PackageManager.PERMISSION_GRANTED)return;if(t.contains("qué tengo hoy")||t.contains("que tengo hoy")||t.contains("mi agenda")){Calendar a=Calendar.getInstance();a.set(Calendar.HOUR_OF_DAY,0);a.set(Calendar.MINUTE,0);long start=a.getTimeInMillis();a.add(Calendar.DAY_OF_YEAR,1);StringBuilder s=new StringBuilder();try(Cursor x=instances(c,start,a.getTimeInMillis())){while(x!=null&&x.moveToNext()){if(s.length()>0)s.append(", ");s.append(x.getString(1));}}say(c,s.length()==0?"No tienes eventos hoy.":"Hoy tienes: "+s);return;}if(c.checkSelfPermission(Manifest.permission.WRITE_CALENDAR)!=PackageManager.PERMISSION_GRANTED)return;if(t.startsWith("elimina evento ")){String name=q.substring(15).trim();long id=find(c,name);if(id>=0){c.getContentResolver().delete(ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI,id),null,null);say(c,"Evento eliminado.");}return;}if(t.startsWith("mueve ")){Matcher m=Pattern.compile("mueve (.+?) a las? (\\d{1,2})(?::(\\d{2}))?",Pattern.CASE_INSENSITIVE).matcher(q);if(m.find()){long id=find(c,m.group(1));if(id>=0){Calendar at=Calendar.getInstance();at.set(Calendar.HOUR_OF_DAY,Integer.parseInt(m.group(2)));at.set(Calendar.MINUTE,m.group(3)==null?0:Integer.parseInt(m.group(3)));ContentValues v=new ContentValues();v.put(CalendarContract.Events.DTSTART,at.getTimeInMillis());v.put(CalendarContract.Events.DTEND,at.getTimeInMillis()+3600000);c.getContentResolver().update(ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI,id),v,null,null);say(c,"Evento actualizado.");}}}}
 private Cursor instances(Context c,long from,long to){android.net.Uri.Builder b=CalendarContract.Instances.CONTENT_URI.buildUpon();ContentUris.appendId(b,from);ContentUris.appendId(b,to);return c.getContentResolver().query(b.build(),new String[]{CalendarContract.Instances.EVENT_ID,CalendarContract.Instances.TITLE},null,null,CalendarContract.Instances.BEGIN);}private long find(Context c,String name){long now=System.currentTimeMillis();try(Cursor x=instances(c,now,now+365L*86400000)){while(x!=null&&x.moveToNext())if(x.getString(1)!=null&&x.getString(1).toLowerCase().contains(name.toLowerCase()))return x.getLong(0);}return-1;}private void say(Context c,String s){c.sendBroadcast(new Intent(ConversationService.EVENT).setPackage(c.getPackageName()).putExtra("type","reply").putExtra("value",s));Intent i=new Intent(c,ConversationService.class).setAction(ConversationService.ACTION_SPEAK).putExtra("text",s);if(Build.VERSION.SDK_INT>=26)c.startForegroundService(i);else c.startService(i);}}
